<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Http\Requests\UploadFileRequest; use App\Http\Responses\ApiResponse; use App\Models\File; use App\Models\Doctor; use App\Models\MedicalRecord; use App\Models\Patient; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class FileController extends Controller { private array $map=['patient'=>Patient::class,'doctor'=>Doctor::class,'medical_record'=>MedicalRecord::class]; private function canAccess(File $file): bool { $u=request()->user(); if($u->isRole('admin') || $file->uploaded_by===$u->id) return true; $model=$file->fileable; if($model instanceof Patient) return $u->patient?->id===$model->id; if($model instanceof Doctor) return $u->doctor?->id===$model->id; if($model instanceof MedicalRecord) return $u->doctor?->id===$model->doctor_id || $u->patient?->id===$model->appointment->patient_id; return false; } public function store(UploadFileRequest $r){ $class=$this->map[$r->fileable_type]; $target=$class::findOrFail($r->fileable_id); $safe=Str::slug(pathinfo($r->file('file')->getClientOriginalName(), PATHINFO_FILENAME)); $path=$r->file('file')->storeAs('private/medical-files', uniqid().'-'.$safe.'.'.$r->file('file')->extension()); $f=$target->files()->create(['file_path'=>$path,'original_name'=>$r->file('file')->getClientOriginalName(),'mime_type'=>$r->file('file')->getMimeType(),'size'=>$r->file('file')->getSize(),'uploaded_by'=>$r->user()->id]); return ApiResponse::success($f,'File uploaded',201); } public function show(File $file){ if(!$this->canAccess($file)) return ApiResponse::error('Forbidden',403); return Storage::download($file->file_path, $file->original_name); } public function destroy(File $file){ if(!$this->canAccess($file)) return ApiResponse::error('Forbidden',403); $file->delete(); return ApiResponse::success(null,'File ditandai dihapus'); } }
